// ── tabs ──────────────────────────────────────────────────────────────────────
function showTab(name, btn) {
  document.querySelectorAll('.tab-content').forEach(t=>t.classList.remove('active'));
  document.querySelectorAll('.main-tab').forEach(b=>b.classList.remove('active'));
  document.getElementById('tab-'+name).classList.add('active');
  btn.classList.add('active');
  document.getElementById('period-bar-informe').style.display = name==='informe' ? 'flex' : 'none';
}

// ── helpers ───────────────────────────────────────────────────────────────────
function fmtArs(n){ return n ? '$ '+Math.round(n).toLocaleString('es-AR') : '—'; }
function fmtPct(n,t){ return t ? (n/t*100).toFixed(1)+'%' : '0%'; }
function badgeE(e){
  const m={'Lead':'badge-grey','En Contacto':'badge-blue','Cotizado':'badge-yellow','Cerrado':'badge-green','Descartado':'badge-red'};
  return `<span class="badge ${m[e]||'badge-grey'}">${e}</span>`;
}
function tagC(c){ return c==='TERRENO'?'<span class="tag-terreno">TERRENO</span>':'<span class="tag-ospif">OSPIF</span>'; }

// ── INFORME COMERCIAL: periodo filter ─────────────────────────────────────────
let periodoActual = 'todos';
function setPeriodo(p, btn) {
  periodoActual = p;
  document.querySelectorAll('#period-bar-informe .period-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  recalcInforme();
}

function recalcInforme() {
  const p = periodoActual;
  const rows = p==='todos' ? CONTACTOS : CONTACTOS.filter(c=>c.mes===p);
  const total = rows.length;
  const emb = {};
  ESTADOS_LIST.forEach(e=>{ emb[e]=rows.filter(c=>c.estado===e).length; });
  const cerr = emb['Cerrado']||0;
  const resp = (emb['En Contacto']||0)+(emb['Cotizado']||0)+cerr;
  const desc = emb['Descartado']||0;
  const ingr = rows.filter(c=>c.estado==='Cerrado').reduce((s,c)=>s+c.cuota,0);
  const gs1  = rows.filter(c=>c.estado==='Cerrado'&&c.plan==='GS100').length;
  const gs2  = rows.filter(c=>c.estado==='Cerrado'&&c.plan==='GS200').length;
  const caps = rows.filter(c=>c.estado==='Cerrado').reduce((s,c)=>s+c.capitas,0);
  const ratio = cerr ? (caps/cerr).toFixed(2) : '0';

  document.getElementById('kpi-total').textContent = total;
  document.getElementById('kpi-cerrados').textContent = cerr;
  document.getElementById('kpi-planes').textContent = `GS100: ${gs1} · GS200: ${gs2}`;
  document.getElementById('kpi-capitas').textContent = caps;
  document.getElementById('kpi-ratio-val').textContent = ratio;
  document.getElementById('kpi-cierre').textContent = fmtPct(cerr,total);
  document.getElementById('kpi-respuesta').textContent = fmtPct(resp,total);
  document.getElementById('kpi-conv').textContent = (cerr+desc)?((cerr/(cerr+desc))*100).toFixed(1)+'%':'0%';
  document.getElementById('kpi-ingresos').textContent = fmtArs(ingr);
  document.getElementById('informe-period-label').textContent = p==='todos'
    ? 'KPIs — Todos los periodos' : `KPIs — ${p}`;

  // pie chart motivos
  renderMotivos(rows);

  // embudo
  const funnelEl = document.getElementById('funnel-container');
  funnelEl.innerHTML='';
  const widths=[100,85,70,55,55];
  ESTADOS_LIST.forEach((e,i)=>{
    const val=emb[e]||0;
    const pct=total?(val/total*100).toFixed(1)+'%':'0%';
    const d=document.createElement('div');
    d.className='funnel-step';
    d.style.cssText=`background:${COLORES_F[i]};width:${widths[i]}%;`;
    d.innerHTML=`<span style="opacity:.9;font-size:12px">${e}</span><span style="font-size:20px;font-weight:800">${val}</span><span style="font-size:11px;opacity:.8">${pct}</span>`;
    funnelEl.appendChild(d);
  });
}

